/** 
 * createMaps() One of the main methods that is used to create the actual maps. Calls on various methods to get user input and create the maps.
 * @exception java.io.IOException throws
 */
public void createMaps() throws IOException {
  if (java.awt.GraphicsEnvironment.isHeadless()) {
    System.out.println("Running in headless mode. Exiting.");
    System.exit(0);
  }
  Image map = loadImage();
  if (map == null) {
    System.out.println("You need to select a map image for this to work");
    System.out.println("Shutting down");
    System.exit(0);
  }
  m_seaZoneOnly = doSeaZone();
  String mapDir = getMapDirectory();
  if (mapDir == null || mapDir.equals("") {
    System.out.println("You need to specify a map name for this to work");
    System.out.println("Shutting down");
    System.exit(0);
  }
  TerritoryData.setMapDir(mapDir);
  Iterator unitIter = TerritoryData.getInstance().getTerritories().iterator();
  while (unitIter.hasNext()) {
    String territoryName = (String) unitIter.next();
    boolean seaZone = territoryName.endsWith("Sea Zone");
    if (!seaZone && m_seaZoneOnly) {
      continue;
    }
    if (seaZone && !m_seaZoneOnly) {
      continue;
    }
    try {
      processImage(territoryName, map);
    } catch (ClassCastException | NullPointerException e) {
      System.out.println("Error processing image for territory: " + territoryName);
      e.printStackTrace();
    }
  }
  System.out.println("All Finished!");
  System.exit(0);
}
